1	package edgefleet
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"strings"
8		"time"
9		"unicode/utf8"
10	)
11	
12	// Heartbeat is one telemetry record reported by a node.
13	//
14	// JSON input uses snake_case field names:
15	//
16	//	node          string   node id (required, non-empty)
17	//	seq           integer  sequence number (required, > 0)
18	//	collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00
19	//	                      (required; year 0000-9999, numeric offset hour 00-23
20	//	                      and minute 00-59 on the minute — +24:00 and a folded
21	//	                      offset such as +00:60 are rejected, not normalised;
22	//	                      a fractional second must be exactly representable at
23	//	                      nanosecond precision — more than nine digits is
24	//	                      accepted only when every digit past the ninth is
25	//	                      zero, never truncated or rounded)
26	//	version       string   version (required, non-empty, valid Unicode text)
27	//	height        integer  block height (required, >= 0)
28	//	missed        integer  cumulative missed duties (required, >= 0)
29	type Heartbeat struct {
30		NodeID      string    `json:"node"`
31		Seq         int64     `json:"seq"`
32		CollectedAt time.Time `json:"collected_at"`
33		Version     string    `json:"version"`
34		Height      int64     `json:"height"`
35		Missed      int64     `json:"missed"`
36	}
37	
38	// heartbeatFields enumerates every field that must be explicitly provided.
39	var heartbeatFields = []string{"node", "seq", "collected_at", "version", "height", "missed"}
40	
41	// fieldIssue classifies the way a field value violates a rule. Together with
42	// the field name and the offending numeric value it identifies the rule that
43	// failed, without carrying any wording. Each trust boundary renders the
44	// failure in its own message style and locates it in its own context, but the
45	// rules themselves — which values are legal — live in the check* functions
46	// below exactly once.
47	type fieldIssue int
48	
49	const (
50		issueEmpty            fieldIssue = iota // a required string is ""
51		issueInvalidUnicode                     // node id or version is not lossless text
52		issueNotPositive                        // integer must be > 0
53		issueNegative                           // integer must be >= 0
54		issueMissingInstant                     // collected_at is the zero instant
55		issueYearOutOfRange                     // collected_at year cannot be written by the saved format
56		issueOffsetOutOfRange                   // collected_at timezone offset is not a whole minute within ±23:59
57	)
58	
59	// fieldValueError names the field whose value rule was violated.
60	type fieldValueError struct {
61		field string
62		issue fieldIssue
63		value int64
64	}
65	
66	// checkNodeIDValue holds the single node-id value rule: non-empty, valid
67	// Unicode text. The raw-JSON boundary additionally checks the un-decoded
68	// token (see validateRawText); for a value already decoded from such a
69	// token the Unicode branch can never fire, but both submit entries and the
70	// stored-data read enforce the same rule through this one function.
71	func checkNodeIDValue(node string) *fieldValueError {
72		if node == "" {
73			return &fieldValueError{field: "node", issue: issueEmpty}
74		}
75		if !utf8.ValidString(node) {
76			return &fieldValueError{field: "node", issue: issueInvalidUnicode}
77		}
78		return nil
79	}
80	
81	// checkVersionValue holds the single version value rule: non-empty, valid
82	// Unicode text. The version is opaque text — Chinese, emoji and a literal "�"
83	// the user typed are all legal, and no format (digits and dots) is imposed —
84	// but it must be losslessly representable: a platform that silently rewrites
85	// invalid bytes to U+FFFD would merge distinct versions into one and make the
86	// version-skew judgement compare text the node never reported. The raw-JSON
87	// boundary additionally checks the un-decoded token (see validateRawText);
88	// for a value already decoded from such a token the Unicode branch can never
89	// fire, but both submit entries and the stored-data read enforce the same
90	// rule through this one function.
91	func checkVersionValue(version string) *fieldValueError {
92		if version == "" {
93			return &fieldValueError{field: "version", issue: issueEmpty}
94		}
95		if !utf8.ValidString(version) {
96			return &fieldValueError{field: "version", issue: issueInvalidUnicode}
97		}
98		return nil
99	}
100	
101	// checkPositiveInt holds the single positive-integer rule (seq).
102	func checkPositiveInt(field string, value int64) *fieldValueError {
103		if value <= 0 {
104			return &fieldValueError{field: field, issue: issueNotPositive, value: value}
105		}
106		return nil
107	}
108	
109	// checkNonNegativeInt holds the single non-negative-integer rule (height,
110	// missed). An explicit zero is genuine telemetry and passes.
111	func checkNonNegativeInt(field string, value int64) *fieldValueError {
112		if value < 0 {
113			return &fieldValueError{field: field, issue: issueNegative, value: value}
114		}
115		return nil
116	}
117	
118	// checkCollectedAtValue holds the context-free collected_at rules shared by
119	// every boundary:
120	//
121	//   - the instant must actually be present (not the zero time);
122	//   - its year must be 0000..9999, the four-digit range the saved RFC3339
123	//     form can write — a year outside it cannot be persisted at all;
124	//   - its UTC offset must be a whole number of minutes no larger than
125	//     ±23:59, the offsets the saved form can write exactly. A ±24:00 offset
126	//     is outside the 00..23 hour bound, and a sub-minute offset (e.g.
127	//     +08:00:30) would silently land on disk as a different instant.
128	//
129	// Checking the decoded instant covers a Heartbeat built directly in Go;
130	// values decoded from JSON text additionally pass validateCollectedAtText,
131	// because time.Parse folds an out-of-range textual offset (+00:60 -> +01:00)
132	// before an instant ever exists to inspect.
133	func checkCollectedAtValue(collected time.Time) *fieldValueError {
134		if collected.IsZero() {
135			return &fieldValueError{field: "collected_at", issue: issueMissingInstant}
136		}
137		if year := collected.Year(); year < minSavedYear || year > maxSavedYear {
138			return &fieldValueError{field: "collected_at", issue: issueYearOutOfRange, value: int64(year)}
139		}
140		if _, offset := collected.Zone(); !isWritableOffset(offset) {
141			return &fieldValueError{field: "collected_at", issue: issueOffsetOutOfRange, value: int64(offset)}
142		}
143		return nil
144	}
145	
146	// Year bounds of the four-digit RFC3339 year the saved format writes.
147	const (
148		minSavedYear = 0
149		maxSavedYear = 9999
150	)
151	
152	// maxWritableOffsetSeconds is 23:59, the largest magnitude UTC offset whose
153	// hour and minute fields both fit the RFC3339 numeric offset (hour 00..23,
154	// minute 00..59). 24:00 is out of range, not an alias for the next day.
155	const maxWritableOffsetSeconds = 23*3600 + 59*60
156	
157	// isWritableOffset reports whether a UTC offset in seconds can be written by
158	// the on-disk RFC3339 form without losing or folding anything: it must be a
159	// whole number of minutes (a sub-minute offset has no representation), and
160	// its magnitude must be no greater than ±23:59.
161	func isWritableOffset(offsetSeconds int) bool {
162		if offsetSeconds%60 != 0 {
163			return false
164		}
165		if offsetSeconds < 0 {
166			offsetSeconds = -offsetSeconds
167		}
168		return offsetSeconds <= maxWritableOffsetSeconds
169	}
170	
171	// formatOffsetSeconds renders a UTC offset in seconds the way it was
172	// declared: ±HH:MM for a whole-minute offset, ±HH:MM:SS when a sub-minute
173	// part is present, so an error can show the exact offset that could not be
174	// saved (e.g. +08:00:45 or -24:00).
175	func formatOffsetSeconds(seconds int) string {
176		sign := "+"
177		if seconds < 0 {
178			sign = "-"
179			seconds = -seconds
180		}
181		hour := seconds / 3600
182		minute := (seconds % 3600) / 60
183		if rem := seconds % 60; rem != 0 {
184			return fmt.Sprintf("%s%02d:%02d:%02d", sign, hour, minute, rem)
185		}
186		return fmt.Sprintf("%s%02d:%02d", sign, hour, minute)
187	}
188	
189	// validateCollectedAtText guards the one gap in time.Parse(RFC3339) that the
190	// instant-level check cannot see: the standard library folds an out-of-range
191	// numeric timezone offset instead of rejecting it — "+00:60" parses as
192	// +01:00 and "+23:60" as +24:00 — and it accepts "+24:00"/"-24:00" even
193	// though the RFC3339 write layout cannot express them. The string has
194	// already passed time.Parse, so its shape is RFC3339 with a "Z" suffix or a
195	// six-character ±HH:MM suffix; here the offset's own hour and minute fields
196	// are required to be 00..23 and 00..59 with no carry-over between them.
197	func validateCollectedAtText(s string) error {
198		// "Z" is the only sign-less offset form; it denotes the zero offset.
199		if strings.HasSuffix(s, "Z") {
200			return nil
201		}
202		if len(s) < 6 {
203			return fmt.Errorf("timezone offset must be Z or ±HH:MM in %q", s)
204		}
205		off := s[len(s)-6:]
206		if (off[0] != '+' && off[0] != '-') || off[3] != ':' {
207			return fmt.Errorf("timezone offset must be Z or ±HH:MM, got %q", s)
208		}
209		hour, ok1 := twoDecimalDigits(off[1:3])
210		minute, ok2 := twoDecimalDigits(off[4:6])
211		if !ok1 || !ok2 {
212			return fmt.Errorf("timezone offset must be Z or ±HH:MM, got %q", s)
213		}
214		if hour > 23 {
215			return fmt.Errorf("timezone offset %s has hour %02d, must be 00-23", off, hour)
216		}
217		if minute > 59 {
218			return fmt.Errorf("timezone offset %s has minute %02d, must be 00-59 (out-of-range minutes are not folded into the hour)", off, minute)
219		}
220		return nil
221	}
222	
223	// twoDecimalDigits parses exactly two ASCII decimal digits.
224	func twoDecimalDigits(s string) (int, bool) {
225		if len(s) != 2 || s[0] < '0' || s[0] > '9' || s[1] < '0' || s[1] > '9' {
226			return 0, false
227		}
228		return int(s[0]-'0')*10 + int(s[1]-'0'), true
229	}
230	
231	// validateCollectedAtFraction guards the second gap in time.Parse(RFC3339)
232	// that the instant-level check cannot see: the standard library silently
233	// truncates a fractional second beyond nine digits, so ".1234567891" and
234	// ".1234567892" both decode to the same nanosecond instant even though the
235	// node reported two different moments. Heartbeat collection times must be
236	// preserved exactly, so such input is refused, never truncated or rounded.
237	// A fraction of at most nine digits always parses exactly, and a longer
238	// fraction is accepted only when every digit past the ninth is zero — the
239	// text then denotes the same instant as its nine-digit prefix (".1234567890"
240	// is ".123456789"). The string has already passed time.Parse, so a "."
241	// can only introduce the fractional second and what follows it up to the
242	// zone suffix is all digits.
243	func validateCollectedAtFraction(s string) error {
244		dot := strings.IndexByte(s, '.')
245		if dot < 0 {
246			return nil
247		}
248		end := dot + 1
249		for end < len(s) && s[end] >= '0' && s[end] <= '9' {
250			end++
251		}
252		frac := s[dot+1 : end]
253		if len(frac) <= 9 {
254			return nil
255		}
256		for i := 9; i < len(frac); i++ {
257			if frac[i] != '0' {
258				return fmt.Errorf("fractional second .%s cannot be represented exactly at nanosecond precision: digit %d is not zero, and digits past the ninth must all be zero (the instant is never truncated or rounded)", frac, i+1)
259			}
260		}
261		return nil
262	}
263	
264	// checkHeartbeatValues runs every context-free field-value rule in the single
265	// rejection order shared by the direct-submit and stored-data boundaries:
266	// node, seq, version, height, missed, then collected_at. It deliberately does
267	// NOT compare against a receive time: reading saved history has no receive
268	// time, and that submit-only rule lives in checkCollectedAtTiming.
269	func checkHeartbeatValues(h Heartbeat) *fieldValueError {
270		if e := checkNodeIDValue(h.NodeID); e != nil {
271			return e
272		}
273		if e := checkPositiveInt("seq", h.Seq); e != nil {
274			return e
275		}
276		if e := checkVersionValue(h.Version); e != nil {
277			return e
278		}
279		if e := checkNonNegativeInt("height", h.Height); e != nil {
280			return e
281		}
282		if e := checkNonNegativeInt("missed", h.Missed); e != nil {
283			return e
284		}
285		return checkCollectedAtValue(h.CollectedAt)
286	}
287	
288	// checkCollectedAtTiming holds the single receive-time rule, which belongs to
289	// submission only: a collection time later than the receive time is refused;
290	// the same instant expressed in another timezone is equal and allowed. The
291	// stored-data read path never calls this, so reading history introduces no
292	// current time and no extra time limit.
293	func checkCollectedAtTiming(collected, receiveTime time.Time) error {
294		if collected.After(receiveTime) {
295			return fmt.Errorf("collected_at %s is later than receive time %s",
296				collected.Format(time.RFC3339), receiveTime.Format(time.RFC3339))
297		}
298		return nil
299	}
300	
301	// directError renders a field rule failure in ValidateHeartbeat's wording,
302	// used when a caller submits an already constructed Heartbeat.
303	func (e *fieldValueError) directError() error {
304		switch {
305		case e.field == "node" && e.issue == issueEmpty:
306			return fmt.Errorf("node id is empty")
307		case e.field == "node" && e.issue == issueInvalidUnicode:
308			return fmt.Errorf("node id is not valid Unicode text: contains invalid UTF-8")
309		case e.field == "seq":
310			return fmt.Errorf("seq must be a positive integer, got %d", e.value)
311		case e.field == "version" && e.issue == issueInvalidUnicode:
312			return fmt.Errorf("version is not valid Unicode text: contains invalid UTF-8")
313		case e.field == "version":
314			return fmt.Errorf("version is empty")
315		case e.field == "height":
316			return fmt.Errorf("height must be >= 0, got %d", e.value)
317		case e.field == "missed":
318			return fmt.Errorf("missed must be >= 0, got %d", e.value)
319		case e.field == "collected_at":
320			switch e.issue {
321			case issueMissingInstant:
322				return fmt.Errorf("collected_at is missing or invalid")
323			case issueYearOutOfRange:
324				return fmt.Errorf("collected_at year %d cannot be saved: year must be 0000-9999", e.value)
325			case issueOffsetOutOfRange:
326				return fmt.Errorf("collected_at timezone offset %s cannot be saved exactly: offset must be a whole minute within -23:59 to +23:59", formatOffsetSeconds(int(e.value)))
327			}
328			return fmt.Errorf("collected_at is missing or invalid")
329		default:
330			return fmt.Errorf("field %q has an invalid value", e.field)
331		}
332	}
333	
334	// decodeError renders a field rule failure in the wording used while decoding
335	// a strict JSON object (submit input and stored records alike).
336	func (e *fieldValueError) decodeError() error {
337		switch {
338		case e.field == "node" && e.issue == issueInvalidUnicode:
339			return fmt.Errorf("node id is not valid Unicode text: contains invalid UTF-8")
340		case e.field == "node":
341			return fmt.Errorf("node must not be empty")
342		case e.field == "seq":
343			return fmt.Errorf("seq must be a positive integer, got %d", e.value)
344		case e.field == "version" && e.issue == issueInvalidUnicode:
345			return fmt.Errorf("version is not valid Unicode text: contains invalid UTF-8")
346		case e.field == "version":
347			return fmt.Errorf("version must not be empty")
348		case e.field == "height":
349			return fmt.Errorf("height must be >= 0, got %d", e.value)
350		case e.field == "missed":
351			return fmt.Errorf("missed must be >= 0, got %d", e.value)
352		case e.field == "collected_at":
353			switch e.issue {
354			case issueMissingInstant:
355				return fmt.Errorf("collected_at is missing or invalid")
356			case issueYearOutOfRange:
357				return fmt.Errorf("collected_at year %d is out of range: year must be 0000-9999", e.value)
358			case issueOffsetOutOfRange:
359				return fmt.Errorf("collected_at timezone offset %s is out of range: offset must be a whole minute within -23:59 to +23:59", formatOffsetSeconds(int(e.value)))
360			}
361			return fmt.Errorf("collected_at is missing or invalid")
362		default:
363			return fmt.Errorf("invalid value for field %q", e.field)
364		}
365	}
366	
367	// storedError renders a field rule failure for a record read from a saved
368	// file, prefixing the 1-based record position as stored-data errors do.
369	func (e *fieldValueError) storedError(position int) error {
370		switch {
371		case (e.field == "node" || e.field == "version") && e.issue == issueInvalidUnicode:
372			return fmt.Errorf("record %d: field %q is not valid Unicode text", position, e.field)
373		case e.field == "node" || e.field == "version":
374			return fmt.Errorf("record %d: field %q must not be empty", position, e.field)
375		case e.field == "seq":
376			return fmt.Errorf("record %d: field %q must be a positive integer, got %d", position, e.field, e.value)
377		case e.field == "height" || e.field == "missed":
378			return fmt.Errorf("record %d: field %q must be >= 0, got %d", position, e.field, e.value)
379		case e.field == "collected_at":
380			switch e.issue {
381			case issueYearOutOfRange:
382				return fmt.Errorf("record %d: field %q year %d is out of range: year must be 0000-9999", position, e.field, e.value)
383			case issueOffsetOutOfRange:
384				return fmt.Errorf("record %d: field %q timezone offset %s is out of range: offset must be a whole minute within -23:59 to +23:59", position, e.field, formatOffsetSeconds(int(e.value)))
385			}
386			return fmt.Errorf("record %d: field %q is missing or invalid", position, e.field)
387		default:
388			return fmt.Errorf("record %d: field %q has an invalid value", position, e.field)
389		}
390	}
391	
392	// ValidateHeartbeat checks the semantic rules for one record. receiveTime is
393	// the moment the platform received the batch; a collection time later than
394	// receive time is rejected. The field-value rules are shared with JSON
395	// parsing and the stored-file read path via checkHeartbeatValues; only the
396	// receive-time comparison is submit-specific.
397	func ValidateHeartbeat(h Heartbeat, receiveTime time.Time) error {
398		if e := checkHeartbeatValues(h); e != nil {
399			return e.directError()
400		}
401		return checkCollectedAtTiming(h.CollectedAt, receiveTime)
402	}
403	
404	// Equal reports whether two records are the same telemetry. Collection times
405	// are compared as instants, so the same moment expressed in different
406	// timezones compares equal.
407	func (h Heartbeat) Equal(o Heartbeat) bool {
408		return h.NodeID == o.NodeID &&
409			h.Seq == o.Seq &&
410			h.Version == o.Version &&
411			h.Height == o.Height &&
412			h.Missed == o.Missed &&
413			h.CollectedAt.Equal(o.CollectedAt)
414	}
415	
416	// ParseHeartbeats parses a JSON array of heartbeat objects. Every field must
417	// be explicitly provided; missing or unknown fields are rejected with a
418	// specific reason.
419	func ParseHeartbeats(data []byte, receiveTime time.Time) ([]Heartbeat, error) {
420		var raw []json.RawMessage
421		if err := json.Unmarshal(data, &raw); err != nil {
422			return nil, fmt.Errorf("input must be a JSON array of heartbeat objects: %w", err)
423		}
424		if len(raw) == 0 {
425			return nil, fmt.Errorf("no heartbeat records provided")
426		}
427		records := make([]Heartbeat, 0, len(raw))
428		for i, r := range raw {
429			h, err := parseOneHeartbeat(r, receiveTime)
430			if err != nil {
431				return nil, fmt.Errorf("record %d: %w", i+1, err)
432			}
433			records = append(records, h)
434		}
435		return records, nil
436	}
437	
438	// rejectNull reports an error when a required field's JSON value is null.
439	// A null value means the node did not report the field, which must not be
440	// silently saved as the zero value.
441	func rejectNull(raw json.RawMessage, field string) error {
442		if bytes.Equal(raw, []byte("null")) {
443			return fmt.Errorf("%s must not be null", field)
444		}
445		return nil
446	}
447	
448	// objectFields collects the fields of one JSON object while enforcing the
449	// single field-uniqueness rule shared by every strict decoder in this
450	// package: within one object, a field name may appear only once. Names are
451	// compared as the JSON strings they decode to, so a plain spelling and a
452	// Unicode-escaped spelling of the same name collide, whether the repeated
453	// value is identical or different. The rule is scoped to the current object:
454	// the same field name appearing in another heartbeat object is unrelated.
455	// Both the submit-input decoder (decodeStrictHeartbeatObject) and the
456	// stored-file envelope decoder (decodeStrictNodeFile) apply the rule through
457	// this type; each boundary keeps its own error wording and its own check
458	// ordering for the rejection.
459	//
460	// A nil map value means the name has been seen but its value not decoded
461	// yet; once decoded, the value is stored under the name.
462	type objectFields map[string]json.RawMessage
463	
464	// check records one occurrence of a field name and reports whether the name
465	// already appeared in this object (duplicate == true).
466	func (o objectFields) check(name string) (duplicate bool) {
467		if _, exists := o[name]; exists {
468			return true
469		}
470		o[name] = nil
471		return false
472	}
473	
474	// has reports whether the field name appeared in this object.
475	func (o objectFields) has(name string) bool {
476		_, exists := o[name]
477		return exists
478	}
479	
480	// decodeStrictHeartbeatObject converts one JSON object's raw bytes into a
481	// Heartbeat while enforcing the field rules at every trust boundary: all
482	// fields must be present and non-null, unknown fields are rejected, and a
483	// field may never appear twice in the same object — even with the same
484	// value, and even when one spelling uses a JSON Unicode escape denoting the
485	// same key (the shared objectFields rule). A plain struct/map unmarshal
486	// would instead keep the last
487	// occurrence and let an absent field masquerade as the zero value. Both the
488	// submit input path and the stored-file read path must use it.
489	func decodeStrictHeartbeatObject(raw json.RawMessage) (Heartbeat, error) {
490		// Walk the object with a streaming decoder so duplicate field names are
491		// detected. Field names are compared as the JSON string they represent:
492		// "missed" and "m\u0069ssed" are the same field. A map-based unmarshal
493		// would silently keep only the last occurrence.
494		dec := json.NewDecoder(bytes.NewReader(raw))
495		tok, err := dec.Token()
496		if err != nil {
497			return Heartbeat{}, fmt.Errorf("record must be a JSON object: %w", err)
498		}
499		if d, ok := tok.(json.Delim); !ok || d != '{' {
500			return Heartbeat{}, fmt.Errorf("record must be a JSON object")
501		}
502	
503		fields := objectFields{}
504		for dec.More() {
505			keyTok, err := dec.Token()
506			if err != nil {
507				return Heartbeat{}, fmt.Errorf("invalid field: %w", err)
508			}
509			key, ok := keyTok.(string)
510			if !ok {
511				return Heartbeat{}, fmt.Errorf("field name must be a string")
512			}
513			if fields.check(key) {
514				return Heartbeat{}, fmt.Errorf("duplicate field %q", key)
515			}
516			var val json.RawMessage
517			if err := dec.Decode(&val); err != nil {
518				return Heartbeat{}, fmt.Errorf("invalid value for field %q: %w", key, err)
519			}
520			fields[key] = val
521		}
522		// Consume the closing brace.
523		if _, err := dec.Token(); err != nil {
524			return Heartbeat{}, fmt.Errorf("invalid record: %w", err)
525		}
526	
527		for _, f := range heartbeatFields {
528			if !fields.has(f) {
529				return Heartbeat{}, fmt.Errorf("missing required field %q", f)
530			}
531		}
532		for k := range fields {
533			if !containsString(heartbeatFields, k) {
534				return Heartbeat{}, fmt.Errorf("unknown field %q", k)
535			}
536		}
537	
538		var h Heartbeat
539	
540		if err := rejectNull(fields["node"], "node"); err != nil {
541			return Heartbeat{}, err
542		}
543		if err := json.Unmarshal(fields["node"], &h.NodeID); err != nil {
544			return Heartbeat{}, fmt.Errorf("node must be a string: %w", err)
545		}
546		if err := validateRawText(fields["node"], "node"); err != nil {
547			return Heartbeat{}, err
548		}
549		if e := checkNodeIDValue(h.NodeID); e != nil {
550			return Heartbeat{}, e.decodeError()
551		}
552	
553		if err := rejectNull(fields["seq"], "seq"); err != nil {
554			return Heartbeat{}, err
555		}
556		if err := json.Unmarshal(fields["seq"], &h.Seq); err != nil {
557			return Heartbeat{}, fmt.Errorf("seq must be an integer: %w", err)
558		}
559		if e := checkPositiveInt("seq", h.Seq); e != nil {
560			return Heartbeat{}, e.decodeError()
561		}
562	
563		if err := rejectNull(fields["collected_at"], "collected_at"); err != nil {
564			return Heartbeat{}, err
565		}
566		var collectedStr string
567		if err := json.Unmarshal(fields["collected_at"], &collectedStr); err != nil {
568			return Heartbeat{}, fmt.Errorf("collected_at must be a string: %w", err)
569		}
570		t, err := time.Parse(time.RFC3339, collectedStr)
571		if err != nil {
572			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
573		}
574		// time.Parse folds out-of-range numeric offsets (+00:60 -> +01:00) and
575		// accepts +24:00; verify the written offset before trusting the fold.
576		if err := validateCollectedAtText(collectedStr); err != nil {
577			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
578		}
579		// time.Parse also silently truncates a fractional second beyond nine
580		// digits; the collection moment must be exactly representable.
581		if err := validateCollectedAtFraction(collectedStr); err != nil {
582			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
583		}
584		h.CollectedAt = t
585	
586		if err := rejectNull(fields["version"], "version"); err != nil {
587			return Heartbeat{}, err
588		}
589		if err := json.Unmarshal(fields["version"], &h.Version); err != nil {
590			return Heartbeat{}, fmt.Errorf("version must be a string: %w", err)
591		}
592		if err := validateRawText(fields["version"], "version"); err != nil {
593			return Heartbeat{}, err
594		}
595		if e := checkVersionValue(h.Version); e != nil {
596			return Heartbeat{}, e.decodeError()
597		}
598	
599		if err := rejectNull(fields["height"], "height"); err != nil {
600			return Heartbeat{}, err
601		}
602		if err := json.Unmarshal(fields["height"], &h.Height); err != nil {
603			return Heartbeat{}, fmt.Errorf("height must be an integer: %w", err)
604		}
605		if e := checkNonNegativeInt("height", h.Height); e != nil {
606			return Heartbeat{}, e.decodeError()
607		}
608	
609		if err := rejectNull(fields["missed"], "missed"); err != nil {
610			return Heartbeat{}, err
611		}
612		if err := json.Unmarshal(fields["missed"], &h.Missed); err != nil {
613			return Heartbeat{}, fmt.Errorf("missed must be an integer: %w", err)
614		}
615		if e := checkNonNegativeInt("missed", h.Missed); e != nil {
616			return Heartbeat{}, e.decodeError()
617		}
618	
619		return h, nil
620	}
621	
622	// validateRawText checks the raw JSON string token of a text field (node or
623	// version) before its decoded value is trusted. encoding/json silently rewrites
624	// invalid UTF-8 bytes and unpaired \u surrogate escapes to U+FFFD, which
625	// would merge distinct texts into one replacement-char value: distinct node
626	// ids would collapse and break the ownership check against stored files, and
627	// distinct versions would collapse into text the node never reported,
628	// corrupting dedup and the version-skew judgement. The raw token must decode
629	// losslessly: every literal byte sequence must be valid UTF-8, and every \u
630	// escape must be a valid scalar value or a properly paired high/low
631	// surrogate pair. A literal "�" (or its \uFFFD escape) is valid text the
632	// user typed and is accepted; only undecodable input is rejected. A \\
633	// escape is consumed as a unit, so text that genuinely contains a backslash
634	// followed by "u" and hex digits is never re-interpreted as an escape.
635	func validateRawText(raw json.RawMessage, field string) error {
636		raw = bytes.TrimSpace(raw)
637		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
638			return fmt.Errorf("%s must be a string", field)
639		}
640		s := raw[1 : len(raw)-1]
641		for i := 0; i < len(s); {
642			c := s[i]
643			if c == '\\' {
644				if i+1 >= len(s) {
645					return fmt.Errorf("%s contains a truncated escape", field)
646				}
647				if s[i+1] != 'u' {
648					i += 2
649					continue
650				}
651				if i+6 > len(s) {
652					return fmt.Errorf("%s contains a truncated \\u escape", field)
653				}
654				r, err := parseHex4(s[i+2 : i+6])
655				if err != nil {
656					return fmt.Errorf("%s contains an invalid \\u escape: %w", field, err)
657				}
658				switch {
659				case r >= 0xD800 && r <= 0xDBFF:
660					// A high surrogate is only valid when immediately followed
661					// by a low-surrogate \u escape.
662					if i+12 > len(s) || s[i+6] != '\\' || s[i+7] != 'u' {
663						return fmt.Errorf("%s contains an unpaired high surrogate \\u%04X", field, r)
664					}
665					lo, err := parseHex4(s[i+8 : i+12])
666					if err != nil {
667						return fmt.Errorf("%s contains an invalid \\u escape: %w", field, err)
668					}
669					if lo < 0xDC00 || lo > 0xDFFF {
670						return fmt.Errorf("%s contains an unpaired high surrogate \\u%04X", field, r)
671					}
672					i += 12
673				case r >= 0xDC00 && r <= 0xDFFF:
674					return fmt.Errorf("%s contains an unpaired low surrogate \\u%04X", field, r)
675				default:
676					i += 6
677				}
678				continue
679			}
680			if c < utf8.RuneSelf {
681				i++
682				continue
683			}
684			// A valid multi-byte rune decodes with size >= 2; size 1 means the
685			// bytes are not valid UTF-8 (including surrogate encodings).
686			_, size := utf8.DecodeRune(s[i:])
687			if size == 1 {
688				return fmt.Errorf("%s contains invalid UTF-8 at byte offset %d", field, i)
689			}
690			i += size
691		}
692		return nil
693	}
694	
695	// parseHex4 parses exactly four hexadecimal digits as a 16-bit value.
696	func parseHex4(b []byte) (rune, error) {
697		v := 0
698		for _, c := range b {
699			var d int
700			switch {
701			case '0' <= c && c <= '9':
702				d = int(c - '0')
703			case 'a' <= c && c <= 'f':
704				d = int(c-'a') + 10
705			case 'A' <= c && c <= 'F':
706				d = int(c-'A') + 10
707			default:
708				return 0, fmt.Errorf("invalid hex digit %q", c)
709			}
710			v = v*16 + d
711		}
712		return rune(v), nil
713	}
714	
715	// parseOneHeartbeat decodes one submit-input record and applies the
716	// submit-only rule that collection time cannot be later than receive time.
717	func parseOneHeartbeat(raw json.RawMessage, receiveTime time.Time) (Heartbeat, error) {
718		h, err := decodeStrictHeartbeatObject(raw)
719		if err != nil {
720			return Heartbeat{}, err
721		}
722		if err := checkCollectedAtTiming(h.CollectedAt, receiveTime); err != nil {
723			return Heartbeat{}, err
724		}
725		return h, nil
726	}
727	
728	func containsString(list []string, s string) bool {
729		for _, v := range list {
730			if v == s {
731				return true
732			}
733		}
734		return false
735	}
