66	func (e *SaveConfirmError) Error() string {
67		switch e.Op {
68		case "open":
69			return fmt.Sprintf("save confirmation failed in directory %s: cannot open directory to confirm node-file replacement: %v", e.Dir, e.Err)
70		case "sync":
71			return fmt.Sprintf("save confirmation failed in directory %s: cannot sync directory to disk after node-file replacement: %v", e.Dir, e.Err)
72		default:
73			return fmt.Sprintf("save confirmation failed in directory %s: %v", e.Dir, e.Err)
74		}
