208		tamperedFile(t, path, `[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00.12345678901Z","version":"1.0","height":100,"missed":0}]`)
209		corruptBefore, err := os.ReadFile(path)
210		if err != nil {
211			t.Fatal(err)
212		}
213	
214		_, err = loadNodeFileFor(store, "n1")
215		if err == nil || !IsCorrupt(err) {
216			t.Fatalf("unrepresentable stored fraction must be corruption, got %v", err)
217		}
218		msg := err.Error()
219		for _, want := range []string{"record 1", "collected_at", ".12345678901", "nanosecond"} {
220			if !strings.Contains(msg, want) {
221				t.Errorf("corruption error must mention %q, got %v", want, err)
222			}
223		}
224		if _, err := store.Health("n1", testBase, "1.0", 0); err == nil || !IsCorrupt(err) {
225			t.Errorf("health must refuse the corrupt data, got %v", err)
226		}
227		if _, err := store.History("n1"); err == nil || !IsCorrupt(err) {
228			t.Errorf("history must refuse the corrupt data, got %v", err)
229		}
230	
231		// Submitting to the corrupt node refuses the whole batch and leaves the
232		// file byte-for-byte intact.
233		good := hb("n1", 2, testBase.Add(-time.Minute), "1.0", 101, 0)
234		if _, _, err := store.Submit([]Heartbeat{good}, testBase); err == nil || !IsCorrupt(err) {
235			t.Fatalf("submit to a corrupt node must be refused as corruption, got %v", err)
236		}
