238			t.Fatalf("corrupt file was overwritten by the refused submit: err=%v", rerr)
239		}
240	}
241	
242	// TestStoredTrailingZeroFractionFileReads proves the legal long form on disk:
243	// a saved record whose fraction only adds trailing zeros past the ninth digit
244	// denotes an exactly representable instant and stays readable.
245	func TestStoredTrailingZeroFractionFileReads(t *testing.T) {
246		dir := t.TempDir()
247		store, err := OpenStore(dir)
248		if err != nil {
249			t.Fatal(err)
250		}
251		path := store.nodePath("n1")
252		tamperedFile(t, path, `[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00.1234567890Z","version":"1.0","height":100,"missed":0}]`)
253	
254		nf, err := loadNodeFileFor(store, "n1")
255		if err != nil {
256			t.Fatalf("trailing-zero fraction must stay readable, got %v", err)
257		}
258		want := time.Date(2026, 10, 1, 11, 59, 0, 123456789, time.UTC)
259		if len(nf.Records) != 1 || !nf.Records[0].CollectedAt.Equal(want) {
260			t.Fatalf("stored instant changed: %+v", nf.Records)
261		}
262		hist, err := store.History("n1")
263		if err != nil {
264			t.Fatal(err)
265		}
266		if len(hist) != 1 || hist[0].CollectedAt.Nanosecond() != 123456789 {
267			t.Errorf("history lost the nanosecond fraction: %+v", hist)
268		}
269	}
270	
271	// TestSameSeqOneNanosecondApartConflicts pins the other side of the rule:
272	// two legal records for the same node and seq whose collection instants
273	// differ by a single nanosecond are a content conflict, not a duplicate.
274	func TestSameSeqOneNanosecondApartConflicts(t *testing.T) {
275		store, err := OpenStore(t.TempDir())
276		if err != nil {
277			t.Fatal(err)
278		}
279		receive := testBase
280		base := time.Date(2026, 10, 1, 11, 59, 0, 123456789, time.UTC)
281		first := hb("n1", 1, base, "1.0", 100, 0)
282		if _, _, err := store.Submit([]Heartbeat{first}, receive); err != nil {
283			t.Fatal(err)
284		}
285		second := hb("n1", 1, base.Add(time.Nanosecond), "1.0", 100, 0)
286		newC, dupC, err := store.Submit([]Heartbeat{second}, receive)
287		if err == nil {
288			t.Fatal("same node+seq one nanosecond apart must conflict, not dedup")
289		}
290		if newC != 0 || dupC != 0 {
291			t.Errorf("conflicted batch counters must be 0/0, got new=%d dup=%d", newC, dupC)
292		}
293		if !strings.Contains(err.Error(), "conflict") {
294			t.Errorf("error must report a content conflict, got %v", err)
295		}
296		hist, herr := store.History("n1")
297		if herr != nil {
298			t.Fatal(herr)
299		}
300		if len(hist) != 1 || !hist[0].Equal(first) {
301			t.Errorf("original record must survive the conflict: %+v", hist)
302		}
303	}
