package edgefleet

import (
	"strings"
	"testing"
	"time"
)

func TestCommaFractionVerify(t *testing.T) {
	receive := time.Date(2026, 10, 2, 0, 0, 0, 0, time.UTC)
	mk := func(stamp string) string {
		return `[{"node":"n1","seq":1,"collected_at":"` + stamp + `","version":"1.0","height":1,"missed":0}]`
	}
	// Rejected: non-zero past the ninth digit, comma form.
	for _, c := range []struct{ stamp, frac string }{
		{"2026-10-01T11:59:00,1234567891Z", ",1234567891"},
		{"2026-10-01T11:59:00,1234567892Z", ",1234567892"},
		{"2026-10-01T11:59:00,0000000000001Z", ",0000000000001"},
		{"2026-10-01T11:59:00,1234567891+08:00", ",1234567891"},
	} {
		recs, err := ParseHeartbeats([]byte(mk(c.stamp)), receive)
		if err == nil {
			t.Fatalf("%s must be rejected", c.stamp)
		}
		if recs != nil {
			t.Fatalf("no partial records, got %v", recs)
		}
		for _, want := range []string{"record 1", "collected_at", c.frac, "nanosecond"} {
			if !strings.Contains(err.Error(), want) {
				t.Errorf("%s: error %q must mention %q", c.stamp, err, want)
			}
		}
	}
	// Accepted: comma forms that are exactly representable.
	for stamp, wantNS := range map[string]int{
		"2026-10-01T11:59:00,5Z":              500000000,
		"2026-10-01T11:59:00,123456789Z":      123456789,
		"2026-10-01T11:59:00,123456789000Z":   123456789,
		"2026-10-01T11:59:00,1234567890+08:00": 123456789,
	} {
		recs, err := ParseHeartbeats([]byte(mk(stamp)), receive)
		if err != nil {
			t.Fatalf("%s must be accepted: %v", stamp, err)
		}
		if recs[0].CollectedAt.Nanosecond() != wantNS {
			t.Errorf("%s: ns=%d, want %d", stamp, recs[0].CollectedAt.Nanosecond(), wantNS)
		}
	}
	// JSON-escaped comma and digit judged on the decoded text.
	esc := `[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00,1234567891Z","version":"1.0","height":1,"missed":0}]`
	if _, err := ParseHeartbeats([]byte(esc), receive); err == nil ||
		!strings.Contains(err.Error(), ",1234567891") {
		t.Errorf("escaped comma form must be rejected quoting the fraction, got %v", err)
	}
	// Comma and dot forms of the same instant are duplicates.
	input := `[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00,123456789000Z","version":"1.0","height":1,"missed":0},` +
		`{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00.123456789Z","version":"1.0","height":1,"missed":0}]`
	recs, err := ParseHeartbeats([]byte(input), receive)
	if err != nil {
		t.Fatal(err)
	}
	if !recs[0].Equal(recs[1]) {
		t.Errorf(",123456789000 and .123456789 must denote the same instant")
	}
}
EOF
cp /tmp/comma_verify_test.go edgefleet/zz_comma_verify_test.go && go test ./edgefleet/ -run TestCommaFractionVerify -v; rm edgefleet/zz_comma_verify_test.go
